**The bug:** `decoded.exp < Date.now() / 1000` uses strict less-than, so when `exp === currentTime` the condition is false and the token passes. It should use `<=`.

**The deeper issue:** `jwt.verify()` already validates expiration and throws `TokenExpiredError` for expired tokens — so the manual check is redundant and creates this off-by-one vulnerability. The catch block also swallows all errors with the same generic message, hiding the distinction between expired vs. malformed tokens.

**Fix:** remove the manual check entirely, and handle JWT error types explicitly in the catch block.

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  if (!process.env.JWT_SECRET) {
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  try {
    // jwt.verify throws TokenExpiredError when exp <= now, covering the boundary case
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // NotBeforeError or unexpected errors
    return res.status(401).json({ error: 'Token not accepted' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**
| Issue | Before | After |
|---|---|---|
| Boundary bug | `exp < now` accepts tokens expiring at `now` | Removed — `jwt.verify` uses `exp <= now` internally |
| Error detail | Single catch swallows all JWT errors | Distinguishes `TokenExpiredError` vs `JsonWebTokenError` vs `NotBeforeError` |
| Missing secret | No guard — `jwt.verify` would throw with cryptic error | Returns 500 early with a clear message |
